    67	import java.math.BigDecimal;
    68	import java.time.LocalDate;
    69	
    70	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
    71	public record ReservationReceipt(
    72	        String title,
    73	        long reservationId,
    74	        String guestName,
    75	        String guestCpf,
    76	        int roomNumber,
    77	        RoomType roomType,
    78	        LocalDate checkIn,
    79	        LocalDate checkOut,
    80	        int nights,
    81	        BigDecimal subtotal,
    82	        BigDecimal discount,
    83	        BigDecimal total) {
    84	
    85	    public ReservationReceipt(Reservation reservation, Room room) {
    86	        this(
    87	                "Comprovante de reserva",
    88	                reservation.id(),
    89	                reservation.guest().name(),
    90	                reservation.guest().cpf(),
    91	                room.number(),
    92	                room.type(),
    93	                reservation.checkIn(),
    94	                reservation.checkOut(),
    95	                reservation.price().nights(),
    96	                reservation.price().subtotal(),
    97	                reservation.price().discount(),
    98	                reservation.price().total());
    99	    }
   100	
   101	    public String text() {
   102	        StringBuilder text = new StringBuilder();
   103	        text.append(title).append(" nº ").append(reservationId).append('\n');
   104	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
   105	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
   106	        text.append("Entrada: ").append(TextFormat.date(checkIn))
   107	                .append(" | Saída: ").append(TextFormat.date(checkOut))
   108	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
   109	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
   110	        if (discount.signum() > 0) {
   111	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
   112	        }
   113	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
   114	        return text.toString();
   115	    }
   116	}
