116	package hotel.reservations;
117	
118	import hotel.rooms.Room;
119	import java.math.BigDecimal;
120	import java.math.RoundingMode;
121	import java.time.LocalDate;
122	import java.time.Month;
123	
124	/**
125	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
126	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
127	 * (half-even) at every step.
128	 */
129	public final class PriceCalculator {
130	
131	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
132	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
133	
134	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
135	        int nights = 0;
136	        BigDecimal subtotal = cents(BigDecimal.ZERO);
137	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
138	            subtotal = subtotal.add(nightPrice(room, night));
139	            nights++;
140	        }
141	        BigDecimal discount = switch (ratePlan) {
142	            case STANDARD -> cents(BigDecimal.ZERO);
143	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
144	        };
145	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
146	    }
147	
148	    BigDecimal nightPrice(Room room, LocalDate night) {
149	        BigDecimal nightlyRate = room.nightlyRate();
150	        if (isHighSeason(night)) {
151	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
152	        }
153	        return cents(nightlyRate);
154	    }
155	
156	    /** High season: from December 15 to the end of February, and the whole of July. */
157	    static boolean isHighSeason(LocalDate date) {
158	        Month month = date.getMonth();
159	        return month == Month.JANUARY
160	                || month == Month.FEBRUARY
161	                || month == Month.JULY
162	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
163	    }
164	
165	    static BigDecimal cents(BigDecimal value) {
166	        return value.setScale(2, RoundingMode.HALF_EVEN);
167	    }
168	}

